#include <stdio.h>

void rotate(int *p, int n) {
    int t = *p;
    for (int i = 0; i < n - 1; i++) {
        *(p + i) = *(p + i + 1);
    }
    *(p + n - 1) = t;
}

int main() {
    int a[5] = {3, 7, 1, 9, 4};
    int *p = a;
    rotate(p, 5);
    rotate(p + 1, 3);
    for (int i = 0; i < 5; i++) {
        printf("%d", *(p + i));
        if (i < 4) printf(" ");
    }
    printf("\n");
    printf("%d\n", *(p + 2) - *p);
    return 0;
}

class Shape {
    int w = 2;
    int area() { return w * w; }
    String info() { return "Shape:" + area(); }
}
class Rect extends Shape {
    int h = 3;
    int area() { return w * h; }
}
class Cube extends Rect {
    int area() { return super.area() * 2; }
    String info() { return "Cube:" + area(); }
}
public class Main {
    public static void main(String[] args) {
        Shape[] arr = { new Shape(), new Rect(), new Cube() };
        int sum = 0;
        for (Shape s : arr) {
            System.out.println(s.info());
            sum += s.area();
        }
        System.out.println(sum);
    }
}

#include <stdio.h>

int cnt = 0;

int f(int n) {
    cnt++;
    if (n <= 1) return 1;
    if (n % 2 == 0) return f(n / 2) + 2;
    return f(n - 1) * 2;
}

int main() {
    int a = f(10);
    int b = f(7);
    printf("%d %d %d\n", a, b, cnt);
    return 0;
}

class Counter {
    static int total = 0;
    int id;
    Counter() {
        this(10);
        total++;
    }
    Counter(int v) {
        id = v + total;
        total += 2;
    }
    static int get() { return total; }
}
public class Main {
