int main() {
    int x = 44;
    int y = 27;
    int a = x & y;
    int b = x | y;
    int c = x ^ y;
    int d = (x << 2) | (y >> 3);
    int cnt = 0;
    int n = c;
    while (n > 0) {
        cnt += n & 1;
        n >>= 1;
    }
    printf("%d %d %d\n", a, b, c);
    printf("%d %d\n", d, cnt);
    return 0;
}

