int acc(int v) {
    static int total = 0;
    int local = 0;
    total += v;
    local += v;
    return total + local;
}

int main() {
    int r = 0;
    for (int i = 1; i <= 4; i++) {
        r = acc(i * 2);
        if (i > 1) printf(" ");
        printf("%d", r);
    }
    printf("\n%d\n", acc(0));
    return 0;
}

public class Main {
    static String conv(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c >= 'a' && c <= 'z') sb.append((char)(c - 32));
            else if (c >= 'A' && c <= 'Z') sb.append((char)(c + 32));
            else sb.append(c);
        }
        return sb.reverse().toString();
    }
    public static void main(String[] args) {
        String s = "Java2Code";
        String r = conv(s);
        System.out.println(r);
        System.out.println(r.indexOf("A") + r.substring(2, 5));
        int cnt = 0;
        for (char c : r.toCharArray()) {
            if (c == 'a' || c == 'A') cnt++;
        }
        System.out.println(cnt);
    }
}

class Counter:
    def __init__(self, start):
        self.value = start
        self.calls = 0

    def step(self, n):
        self.calls += 1
        if n == 0:
            return self.value
        if n % 2 == 0:
            self.value += n // 2
        else:
            self.value -= n % 3
        return self.step(n - 1)

c = Counter(10)
print(c.step(5))
print(c.calls)
c2 = Counter(-7)
print(c2.value // 2, c2.value % 3)
